import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code with shared memory optimization
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Start index of the tile in A
    int aBegin = N * BLOCK_SIZE * by;
    // Start index of the tile in B
    int bBegin = BLOCK_SIZE * bx;
    // End index of the tile in A
    int aEnd = aBegin + N - 1;

    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Accumulator for each thread
    float c_val = 0.0f;

    // Loop over the tiles
    for (int a = aBegin, b = bBegin; a <= aEnd; a += BLOCK_SIZE, b += BLOCK_SIZE * N) {
        // Load tile of A into shared memory
        if (a + tx + N * ty < N * N) {
            As[ty][tx] = A[a + tx + N * ty];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        if (b + tx + N * ty < N * N) {
            Bs[ty][tx] = B[b + tx + N * ty];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        // Synchronize to ensure tiles are loaded
        __syncthreads();

        // Compute partial product for the tile
        for (int k = 0; k < BLOCK_SIZE; k++) {
            c_val += As[ty][k] * Bs[k][tx];
        }

        // Synchronize before loading next tile
        __syncthreads();
    }

    // Compute global row and column indices
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = c_val;
    }
}

torch::Tensor matmul_forward(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Use block size 32x32
    const int BLOCK_SIZE = 32;
    dim3 blockDim(BLOCK_SIZE, BLOCK_SIZE);
    dim3 gridDim((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    // Launch kernel
    matmul_kernel<BLOCK_SIZE><<<gridDim, blockDim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_forward", &matmul_forward, "Matrix multiplication forward");
}
"""

# Load the CUDA extension
matmul_cuda = load_inline(
    name='matmul_cuda',
    cpp_sources="",
    cuda_sources=cuda_source,
    extra_cuda_cflags=["-O3"],
    verbose=True
)

