    int aBegin = N * BLOCK_SIZE * by;
    int bBegin = BLOCK_SIZE * bx;
    int aStep = BLOCK_SIZE;
    int bStep = BLOCK_SIZE * N;

    // Prefetch first tile
    int aEnd = aBegin + N - 1;

    // Vectorized loads
    float4* A_vec = (float4*)A;
    float4* B_vec = (float4*)B;
    float4* As_vec = (float4*)As;
    float4* Bs_vec = (float4*)Bs;

    for (int a = aBegin, b = bBegin; a <= aEnd; a += aStep, b += bStep) {
        // Load tile of A into shared memory using float4
        int aIdx = a + ty * BLOCK_SIZE + tx * 4;
        if (aIdx + 3 < N * N) {
            As_vec[ty * (BLOCK_SIZE/4) + tx] = A_vec[aIdx / 4];
        } else {
            // Handle boundary conditions
            for (int i = 0; i < 4; i++) {
                int idx = aIdx + i;
                int row = idx / N;
                int col = idx % N;
                if (row < N && col < N) {
                    As[ty][tx*4 + i] = A[idx];
                } else {
                    As[ty][tx*4 + i] = 0.0f;
                }
            }
        }

        // Load tile of B into shared memory using float4
        int bIdx = b + ty * BLOCK_SIZE + tx * 4;
        if (bIdx + 3 < N * N) {
            Bs_vec[ty * (BLOCK_SIZE/4) + tx] = B_vec[bIdx / 4];
        } else {
            // Handle boundary conditions
            for (int i = 0; i < 4; i++) {
                int idx = bIdx + i;
                int row = idx / N;
                int col = idx % N;
