#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Accumulator for each thread
    float c_val = 0.0f;

    // Loop over the tiles
    for (int tile = 0; tile < N; tile += BLOCK_SIZE) {
        // Load tile of A into shared memory with coalesced access
        int a_row = by * BLOCK_SIZE + ty;
        int a_col = tile + tx;

        if (a_row < N && a_col < N) {
            As[ty][tx] = A[a_row * N + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory with coalesced access
        int b_row = tile + ty;
        int b_col = bx * BLOCK_SIZE + tx;

        if (b_row < N && b_col < N) {
            Bs[ty][tx] = B[b_row * N + b_col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial product with loop unrolling
        for (int k = 0; k < BLOCK_SIZE; k += UNROLL_FACTOR) {
            // Unroll the loop to reduce instruction overhead
            c_val += As[ty][k] * Bs[k][tx];
            if (k+1 < BLOCK_SIZE) c_val += As[ty][k+1] * Bs[k+1][tx];
            if (k+2 < BLOCK_SIZE) c_val += As[ty][k+2] * Bs[k+2][tx];
            if (k+3 < BLOCK_SIZE) c_val += As[ty][k+3] * Bs[k+3][tx];
